'use client';  // Assure-toi que le fichier soit traité comme un composant client

import { useState, useEffect } from 'react';
import axios from 'axios';
import Link from 'next/link';
import { IconButton } from '@mui/material';
import { Add as AddIcon, Edit as EditIcon, Delete as DeleteIcon } from '@mui/icons-material';
import Sidebar from "../../components/sidebar";  // Import Sidebar component
import Navbar from "../../components/Navbar";    // Import Navbar component

export default function ListUser() {
  const [etudiants, setUsers] = useState([]);
  const [file, setFile] = useState(null); // State to hold the file
  const [message, setMessage] = useState(""); // Message feedback
  const [dragging, setDragging] = useState(false); // Dragging state for file drop
  const [loading, setLoading] = useState(false); // Loading state for file upload

  useEffect(() => {
    getUsers();
  }, []);

  const getUsers = async () => {
    try {
      const response = await axios.get('http://localhost:5000/api/etudiants');
      setUsers(response.data);
    } catch (err) {
      console.error("Erreur lors de la récupération des utilisateurs :", err);
    }
  };

  const deleteUser = async (id) => {
    if (!window.confirm("Voulez-vous vraiment supprimer cet utilisateur ?")) return;

    try {
      await axios.delete(`http://localhost:5000/api/deleteetudiant/${id}`);
      getUsers();
    } catch (err) {
      console.error("Erreur lors de la suppression de l'utilisateur :", err);
    }
  };

  const handleFileChange = (e) => {
    if (e.target.files && e.target.files.length > 0) {
      setFile(e.target.files[0]);
    }
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    setDragging(true);
  };

  const handleDragLeave = () => {
    setDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setDragging(false);
    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      setFile(e.dataTransfer.files[0]);
    }
  };
  const handleUpload = async () => {
    if (!file) {
      setMessage("Veuillez choisir un fichier.");
      return;
    }
    setLoading(true);
    setMessage("");
  
    const formData = new FormData();
    formData.append("file", file);
  
    try {
      const response = await axios.post('http://localhost:5000/api/import-data', formData, {
        headers: { 'Content-Type': 'multipart/form-data' }
      });
  
      if (response.data?.message) {
        setMessage(response.data.message);
      } else {
        setMessage("Données extraites et importées avec succès !");
        getUsers(); // Re-fetch users after successful import
      }
    } catch (error) {
      console.error("Erreur lors de l'importation :", error);
      setMessage(error instanceof Error ? `Erreur lors de l'importation : ${error.message}` : "Erreur inconnue lors de l'importation.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex h-screen min-h-screen w-screen">
      {/* Sidebar and Navbar layout */}
      <Sidebar className="h-screen hidden lg:block" /> {/* Sidebar hidden on small screens */}
      <div className="w-full flex flex-col h-screen">
        <Navbar />
        <div className="w-full flex-1 py-5 px-6 overflow-hidden">
          {/* Section Ajouter un étudiant et Importer les données */}
          <div className="flex flex-col sm:flex-row justify-between items-center mb-6">
            {/* Ajouter un étudiant */}
            <Link href="/users/createEtu">
              <button className="bg-blue-500 text-white p-3 rounded-full flex items-center justify-center hover:bg-blue-600 transition duration-200 mb-3 sm:mb-0">
                <AddIcon className="mr-2" />
                Ajouter un étudiant
              </button>
            </Link>
            
            {/* Importer des données */}
            <div className="max-w-full sm:max-w-md p-4 text-right mb-3 border rounded shadow bg-white">
              <h1 className="text-md font-semibold mb-2">Importer les informations des étudiants</h1>
              <div
                onDragOver={handleDragOver}
                onDragLeave={handleDragLeave}
                onDrop={handleDrop}
                className={`border-2 border-dashed p-3 text-center ${dragging ? 'bg-gray-200' : 'bg-white'}`}
              >
                {file ? <p>{file.name}</p> : <p>Glissez et déposez un fichier ici ou cliquez pour sélectionner</p>}
                <input type="file" accept=".xlsx, .xls" onChange={handleFileChange} className="hidden" id="fileInput" />
                <label htmlFor="fileInput" className="cursor-pointer text-blue-600">Sélectionner un fichier</label>
              </div>
              <button
                onClick={handleUpload}
                disabled={loading}
                className="mt-2 px-3 py-1 bg-blue-500 text-white rounded disabled:bg-gray-400"
              >
                {loading ? "Importation..." : "Importer"}
              </button>
              {message && <p className="mt-2 text-red-600 text-sm">{message}</p>}
            </div>
          </div>

          {/* Titre de la page */}
          <h1 className="text-3xl font-semibold mb-6 text-center text-gray-800">Liste des étudiants</h1>

          {/* Tableau des étudiants */}<div className="overflow-x-auto overflow-y-auto max-h-[500px]">
  <table className="min-w-full bg-gray border border-gray-300 rounded-lg shadow-md">

              <thead className="bg-blue-700 text-white">
                <tr>
                  <th className="border px-6 py-4 text-left">ID</th>
                  <th className="border px-6 py-4 text-left">Nom</th>
                  <th className="border px-6 py-4 text-left">Prénom</th>
                  <th className="border px-6 py-4 text-left">Email</th>
                  <th className="border px-6 py-4 text-left">Mot de Passe</th>
                  <th className="border px-6 py-4 text-left">Année</th>
                  <th className="border px-6 py-4 text-left">Classe</th>
                  <th className="border px-6 py-4 text-left">Filière</th>
                  <th className="border px-6 py-4 text-left">Actions</th>
                </tr>
              </thead>
              <tbody>
                {etudiants.map((etudiant, index) => (
                  <tr key={etudiant.idEtudiant} className={index % 2 === 0 ? 'bg-blue-100' : 'bg-white'}>
                    <td className="border px-6 py-4">{etudiant.idEtudiant}</td>
                    <td className="border px-6 py-4">{etudiant.nom}</td>
                    <td className="border px-6 py-4">{etudiant.prenom}</td>
                    <td className="border px-6 py-4">{etudiant.email}</td>
                    <td className="border px-6 py-4">{etudiant.motDePasse}</td>
                    <td className="border px-6 py-4">{etudiant.annee}</td>
                    <td className="border px-6 py-4">{etudiant.classe}</td>
                    <td className="border px-6 py-4">{etudiant.filiere}</td>
                    <td className="border px-6 py-4 flex justify-center space-x-3">
                      <Link href={`/users/edit/${etudiant.idEtudiant}`}>
                        <IconButton color="info" title="Modifier l'utilisateur">
                          <EditIcon />
                        </IconButton>
                      </Link>
                      <IconButton color="error" onClick={() => deleteUser(etudiant.idEtudiant)} title="Supprimer l'utilisateur">
                        <DeleteIcon />
                      </IconButton>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        </div>
      </div>
    </div>
  );
}
